const base = '(banjir OR kebanjiran OR genangan OR \"air naik\" OR \"jalan terendam\" OR \"sungai meluap\" OR rob) (Jakarta OR Bekasi OR Depok OR Tangerang)';

return [
  { json: { query_group: 'x', q: `${base} site:x.com` } },
  { json: { query_group: 'short_video', q: `${base} (site:tiktok.com OR site:instagram.com)` } },
  { json: { query_group: 'youtube', q: `${base} site:youtube.com` } },
  { json: { query_group: 'web_news', q: `${base} -site:x.com -site:tiktok.com -site:instagram.com` } },
];

const positive = ['banjir', 'kebanjiran', 'genangan', 'terendam', 'air naik', 'meluap', 'rob'];
const impact = ['jalan', 'rumah', 'kendaraan', 'sungai', 'drainase', 'warga', 'evakuasi'];
const negative = ['banjir diskon', 'banjir order', 'banjir hadiah', 'banjir dukungan', 'game', 'film'];
const locations = [
  { aliases: ['kampung melayu', 'kp melayu'], name: 'Kampung Melayu', lat: -6.2245, lng: 106.8662 },
  { aliases: ['bidara cina'], name: 'Bidara Cina', lat: -6.2291, lng: 106.8670 },
  { aliases: ['kelapa gading'], name: 'Kelapa Gading', lat: -6.1588, lng: 106.9056 },
  { aliases: ['cawang'], name: 'Cawang', lat: -6.2451, lng: 106.8753 },
  { aliases: ['pluit'], name: 'Pluit', lat: -6.1265, lng: 106.7904 },
  { aliases: ['penjaringan'], name: 'Penjaringan', lat: -6.1177, lng: 106.7839 },
  { aliases: ['cengkareng'], name: 'Cengkareng', lat: -6.1527, lng: 106.7447 },
  { aliases: ['pesanggrahan'], name: 'Pesanggrahan', lat: -6.2554, lng: 106.7636 }
];

function normalizeUrl(value) {
  try {
    const url = new URL(value);
    url.search = '';
    url.hash = '';
    return url.toString().replace(/\/$/, '').slice(0, 700);
  } catch {
    return String(value || '').split('?')[0].split('#')[0].slice(0, 700);
  }
}

function platformFromUrl(url) {
  const value = url.toLowerCase();
  if (value.includes('x.com') || value.includes('twitter.com')) return 'x';
  if (value.includes('tiktok.com')) return 'tiktok';
  if (value.includes('instagram.com')) return 'instagram';
  if (value.includes('youtube.com') || value.includes('youtu.be')) return 'youtube';
  return 'web';
}

const output = [];
for (const input of $input.all()) {
  const body = input.json.body ?? input.json;
  const results = [
    ...(Array.isArray(body.organic_results) ? body.organic_results : []),
    ...(Array.isArray(body.news_results) ? body.news_results : [])
  ];

  for (const result of results) {
    const sourceUrl = normalizeUrl(result.link);
    if (!sourceUrl) continue;

    const text = `${result.title ?? ''} ${result.snippet ?? ''}`.toLowerCase();
    const positiveHits = positive.filter((term) => text.includes(term)).length;
    const negativeHits = negative.filter((term) => text.includes(term)).length;
    if (positiveHits === 0 || negativeHits > 0) continue;

    const matchedLocation = locations.find((loc) => loc.aliases.some((alias) => text.includes(alias)));
    const impactHits = impact.filter((term) => text.includes(term)).length;
    const position = Number(result.position ?? 100);
    const relevance = Math.min(100, positiveHits * 25 + impactHits * 8 + (matchedLocation ? 20 : 0));
    const discovery = Math.min(100, Math.max(0, 45 - position) + relevance * 0.35 + (result.thumbnail ? 15 : 0));

    output.push({
      json: {
        platform: platformFromUrl(sourceUrl),
        external_id: sourceUrl,
        source_url: sourceUrl,
        title: result.title ?? null,
        text_content: result.snippet ?? null,
        source_published_text: result.date ?? null,
        published_at: null,
        collected_at: new Date().toISOString().slice(0, 19).replace('T', ' '),
        latitude: matchedLocation?.lat ?? null,
        longitude: matchedLocation?.lng ?? null,
        location_name: matchedLocation?.name ?? null,
        location_method: matchedLocation ? 'text_alias' : 'unknown',
        location_confidence: matchedLocation ? 0.6 : 0,
        search_position: Number.isFinite(position) ? position : null,
        relevance_score: Number(relevance.toFixed(2)),
        discovery_score: Number(discovery.toFixed(2)),
        collection_method: 'serpapi_google',
        raw_payload: JSON.stringify({
          title: result.title ?? null,
          link: result.link ?? null,
          snippet: result.snippet ?? null,
          date: result.date ?? null,
          position: result.position ?? null,
          displayed_link: result.displayed_link ?? null,
          thumbnail: result.thumbnail ?? null
        })
      }
    });
  }
}

return output;
